const errors = {}

/** `int` overflows the TypeScript runtime's range ±(2^53 - 1) in its output. */
export const Overflow = Roadbook.make<OverflowDef>(ir, "Overflow", errors)

// ---- machine: Settle ----

export interface SettleDef extends Roadbook.MachineDef {
  readonly name: "Settle"
  readonly input: {}
  readonly output: void
  readonly error: never
  readonly event: never
  readonly emits: never
  readonly state: "Settle" | "Settle.Spin"
  readonly fns: {}
  readonly actions: {}
  readonly tasks: {}
  readonly machines: {}
}

/** Settles forever: every microstep takes the `always` again. */
export const Settle = Roadbook.make<SettleDef>(ir, "Settle", errors)

// ---- machine: Early ----

export interface EarlyDef extends Roadbook.MachineDef {
  readonly name: "Early"
  readonly input: {}
  readonly output: number
  readonly error: never
  readonly event: never
  readonly emits: never
  readonly state: "Early" | "Early.Over"
  readonly fns: {}
  readonly actions: {}
  readonly tasks: {}
  readonly machines: {}
}

/** Reads `a` before it has a value, in `b`'s initial value. */
export const Early = Roadbook.make<EarlyDef>(ir, "Early", errors)

// ---- machine: Leftover ----

export const Go = Schema.TaggedStruct("Go", {})
export type Go = typeof Go.Type

export interface LeftoverDef extends Roadbook.MachineDef {
  readonly name: "Leftover"
  readonly input: {}
  readonly output: void
  readonly error: never
  readonly event: Go
  readonly emits: never
  readonly state: "Leftover" | "Leftover.Outer" | "Leftover.Outer.Inner" | "Leftover.Over"
  readonly fns: {}
  readonly actions: { readonly log: { readonly what: string } }
  readonly tasks: {
    readonly work: { readonly args: {}; readonly success: number; readonly error: never }
  }
  readonly machines: {}
}

/** Outer's work is cancelled after Inner's exit effect, so a defect there leaves it running. */
export const Leftover = Roadbook.make<LeftoverDef>(ir, "Leftover", errors)

// ---- machine: Payload ----

export interface PayloadDef extends Roadbook.MachineDef {
  readonly name: "Payload"
  readonly input: {}
  readonly output: Schema.Json
  readonly error: never
  readonly event: never
  readonly emits: never
  readonly state: "Payload" | "Payload.Over"
  readonly fns: { readonly payload: { readonly args: {}; readonly returns: Schema.Json } }
  readonly actions: {}
  readonly tasks: {}
  readonly machines: {}
}

/** Ends with whatever the host's `payload` returns, which must be JSON. */
export const Payload = Roadbook.make<PayloadDef>(ir, "Payload", errors)

// ---- machine: Generic ----

export interface GenericDef extends Roadbook.MachineDef {
  readonly name: "Generic"
  readonly input: { readonly boxes: Boxes<Duration.Duration> }
  readonly output: Boxes<Duration.Duration>
  readonly error: never
  readonly event: never
  readonly emits: never
  readonly state: "Generic" | "Generic.Over"
  readonly fns: {
    readonly withLongest: {
      readonly args: { readonly boxes: Boxes<Duration.Duration> }
      readonly returns: Boxes<Duration.Duration>
    }
  }
  readonly actions: {}
  readonly tasks: {}
  readonly machines: {}
}

/** Ends with what the host's `withLongest` makes of its map of generic records of durations. */
export const Generic = Roadbook.make<GenericDef>(ir, "Generic", errors)

